INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Sterntopologie immer die einfachste?', 2, '[{"text": "Ja", "correct": true, "because": "Zentraler Punkt, einfache Verwaltung"}, {"text": "Nein", "correct": false, "because": "Mesh kann simpler wirken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Topologie wähle ich für hohe Ausfallsicherheit?', 3, '[{"text": "Mesh", "correct": true, "because": "Mehrfache Verbindungen"}, {"text": "Stern", "correct": false, "because": "Zentraler Ausfallpunkt"}, {"text": "Ring", "correct": false, "because": "Ein Bruch stoppt alles"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Ringtopologie nützlich?', 5, '[{"text": "Gleichmäßiger Datenfluss", "correct": true, "because": "Rundum-Verbindung"}, {"text": "Einfache Fehlererkennung", "correct": true, "because": "Klarer Datenweg"}, {"text": "Hohe Skalierbarkeit", "correct": false, "because": "Schwierig zu erweitern"}, {"text": "Geringe Kosten", "correct": false, "because": "Verkabelung teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Stern hat einen zentralen Punkt. b) Mesh ist kostengünstig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Mesh ist teuer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Topologie für ein kleines Büro?', 4, '[{"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Verkabelungsaufwand", "correct": false, "because": "Kosten relevant"}, {"text": "Maximale Redundanz", "correct": true, "because": "Übertrieben für klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Ringtopologie noch oft genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Veraltet, Stern dominiert"}, {"text": "Ja", "correct": false, "because": "Selten im Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für ein Heimnetzwerk?', 3, '[{"text": "Einfache Verwaltung", "correct": true, "because": "Stern ist ideal"}, {"text": "Hohe Redundanz", "correct": false, "because": "Nicht nötig"}, {"text": "Komplexe Struktur", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Meshtopologie?', 5, '[{"text": "Ausfallsicherheit", "correct": true, "because": "Mehrere Pfade"}, {"text": "Flexibilität", "correct": true, "because": "Leicht anpassbar"}, {"text": "Geringe Kosten", "correct": false, "because": "Verkabelung teuer"}, {"text": "Einfache Installation", "correct": false, "because": "Komplexer Aufbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Stern ist leicht skalierbar. b) Ring ist redundant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ring hat Schwachstelle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Schulnetzwerk?', 4, '[{"text": "Zentrale Verwaltung", "correct": false, "because": "Stern ideal"}, {"text": "Stabile Verbindungen", "correct": false, "because": "Wichtig für Zuverlässigkeit"}, {"text": "Volle Mesh-Struktur", "correct": true, "because": "Zu teuer und komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Meshtopologie für kleine Netze geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Zu aufwendig"}, {"text": "Ja", "correct": false, "because": "Stern oft besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für eine Sterntopologie entscheidend?', 4, '[{"text": "Zentraler Switch", "correct": true, "because": "Kern der Struktur"}, {"text": "Einfache Verkabelung", "correct": true, "because": "Wenig Aufwand"}, {"text": "Hohe Redundanz", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Ringtopologie keine Switches braucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Direkte Verbindungen"}, {"text": "Nein", "correct": false, "because": "Moderne Varianten nutzen Switches"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein Rechenzentrum?', 3, '[{"text": "Redundanz", "correct": true, "because": "Mesh für Ausfallsicherheit"}, {"text": "Minimale Verkabelung", "correct": false, "because": "Sekundär"}, {"text": "Einfache Struktur", "correct": false, "because": "Komplexität akzeptabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mesh hat viele Verbindungen. b) Stern ist schwer erweiterbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Stern leicht skalierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Ringtopologie?', 5, '[{"text": "Einzelner Ausfallpunkt", "correct": true, "because": "Bruch stoppt Netz"}, {"text": "Schwere Skalierung", "correct": true, "because": "Neue Geräte kompliziert"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}, {"text": "Einfache Wartung", "correct": false, "because": "Nicht gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Topologie für IoT unwichtig?', 3, '[{"text": "Energieeffizienz", "correct": false, "because": "Wichtig für Geräte"}, {"text": "Einfache Verwaltung", "correct": false, "because": "Nötig für viele Knoten"}, {"text": "Maximale Redundanz", "correct": true, "because": "Oft übertrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Sterntopologie teurer als Ring?', 3, '[{"text": "Ja", "correct": true, "because": "Zentraler Switch kostet"}, {"text": "Nein", "correct": false, "because": "Ring kann günstiger sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mesh in WLAN-Netzen üblich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Verbessert Reichweite"}, {"text": "Nein", "correct": false, "because": "Häufig eingesetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Topologie wähle ich für ein einfaches LAN?', 4, '[{"text": "Stern", "correct": true, "because": "Einfach und effizient"}, {"text": "Mesh", "correct": false, "because": "Zu komplex"}, {"text": "Ring", "correct": false, "because": "Veraltet"}]');
